/**
 * Relative dates for date / date-time arguments. Generated by typeship — https://typeship.dev
 *
 * Agents rarely know "now" and often do know "a week ago", so date-shaped
 * arguments of the CLI and the MCP server accept, besides an absolute
 * ISO 8601 value, a relative form resolved here against the clock:
 *
 *   now | today | yesterday | tomorrow
 *   -P7D, +PT1H           signed ISO 8601 durations (negative = in the past)
 *   -7d, +2h, -1w         signed shorthand: s m h d w mo y
 *   7 days ago, in 2 weeks
 *
 * An unsigned duration ("7d", "P1D") is ambiguous and rejected with the two
 * spellings that are not. Anything else passes through untouched; the API
 * validates absolute values. Zero dependencies.
 */

export type DateKind = "date" | "date-time";

const UNIT_MS: Record<string, number> = {
  s: 1000, sec: 1000, second: 1000,
  m: 60_000, min: 60_000, minute: 60_000,
  h: 3_600_000, hr: 3_600_000, hour: 3_600_000,
  d: 86_400_000, day: 86_400_000,
  w: 604_800_000, wk: 604_800_000, week: 604_800_000,
};
const CALENDAR_UNITS = new Set(["mo", "month", "y", "yr", "year"]);

const HINT = "Use a signed form: -7d or -P7D for seven days ago, +7d or +P7D for seven days ahead; or an absolute ISO 8601 value.";

/** The forms a date-shaped argument accepts, for descriptions and help. */

function shift(base: Date, amount: number, unit: string): Date {
  const d = new Date(base.getTime());
  if (CALENDAR_UNITS.has(unit)) {
    if (unit.startsWith("y")) d.setUTCFullYear(d.getUTCFullYear() + amount);
    else d.setUTCMonth(d.getUTCMonth() + amount);
    return d;
  }
  return new Date(d.getTime() + amount * (UNIT_MS[unit] ?? 0));
}

function startOfUtcDay(d: Date): Date {
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
}

function format(d: Date, kind: DateKind): string {
  return kind === "date" ? d.toISOString().slice(0, 10) : d.toISOString();
}

/** Apply a signed ISO 8601 duration (P1Y2M3W4DT5H6M7S) to a date. */
function applyIsoDuration(base: Date, sign: number, body: string): Date | null {
  const m = /^P(?:(\d+)Y)?(?:(\d+)M)?(?:(\d+)W)?(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+(?:\.\d+)?)S)?)?$/i.exec(body);
  if (!m || body.toUpperCase() === "P" || body.toUpperCase() === "PT") return null;
  let d = new Date(base.getTime());
  const [, y, mo, w, day, h, min, s] = m;
  if (y) d = shift(d, sign * Number(y), "y");
  if (mo) d = shift(d, sign * Number(mo), "mo");
  if (w) d = shift(d, sign * Number(w), "w");
  if (day) d = shift(d, sign * Number(day), "d");
  if (h) d = shift(d, sign * Number(h), "h");
  if (min) d = shift(d, sign * Number(min), "m");
  if (s) d = new Date(d.getTime() + sign * Number(s) * 1000);
  return d;
}

/**
 * Resolve a relative date expression. `null` means "not a relative form,
 * pass the value through"; `{ error }` means it looked relative but is
 * ambiguous or malformed; `{ value }` is the absolute value in the
 * argument's format (YYYY-MM-DD for date, ISO instant for date-time).
 */
export function relativeDate(text: string, kind: DateKind, now: Date = new Date()): { value: string } | { error: string } | null {
  const t = text.trim();
  const lower = t.toLowerCase();
  if (lower === "now") return { value: format(now, kind) };
  if (lower === "today") return { value: format(kind === "date" ? now : startOfUtcDay(now), kind) };
  if (lower === "yesterday") return { value: format(shift(kind === "date" ? now : startOfUtcDay(now), -1, "d"), kind) };
  if (lower === "tomorrow") return { value: format(shift(kind === "date" ? now : startOfUtcDay(now), 1, "d"), kind) };

  // Signed ISO 8601 duration: -P7D, +PT1H. Unsigned P7D is ambiguous.
  const iso = /^([+-])?(P[\dYMWDTHS.]+)$/i.exec(t);
  if (iso) {
    const d = applyIsoDuration(now, iso[1] === "-" ? -1 : 1, iso[2]!);
    if (!d) return null; // not a duration after all; let the API judge it
    if (!iso[1]) return { error: "\"" + t + "\" does not say which direction. " + HINT };
    return { value: format(d, kind) };
  }

  // Signed shorthand: -7d, +2h, -1w, -3mo, +1y. Unsigned is ambiguous.
  const short = /^([+-])?(\d+)\s*(s|sec|seconds?|m|min|minutes?|h|hrs?|hours?|d|days?|w|wks?|weeks?|mo|months?|y|yrs?|years?)$/i.exec(t);
  if (short) {
    if (!short[1]) return { error: "\"" + t + "\" does not say which direction. " + HINT };
    const unit = normalizeUnit(short[3]!);
    return { value: format(shift(now, (short[1] === "-" ? -1 : 1) * Number(short[2]), unit), kind) };
  }

  // "7 days ago", "in 2 weeks", "2 hours from now".
  const ago = /^(\d+)\s*(s|sec|seconds?|m|min|minutes?|h|hrs?|hours?|d|days?|w|wks?|weeks?|mo|months?|y|yrs?|years?)\s+ago$/i.exec(t);
  if (ago) return { value: format(shift(now, -Number(ago[1]), normalizeUnit(ago[2]!)), kind) };
  const ahead = /^(?:in\s+(\d+)\s*(s|sec|seconds?|m|min|minutes?|h|hrs?|hours?|d|days?|w|wks?|weeks?|mo|months?|y|yrs?|years?)|(\d+)\s*(s|sec|seconds?|m|min|minutes?|h|hrs?|hours?|d|days?|w|wks?|weeks?|mo|months?|y|yrs?|years?)\s+from\s+now)$/i.exec(t);
  if (ahead) {
    const n = Number(ahead[1] ?? ahead[3]);
    const unit = normalizeUnit((ahead[2] ?? ahead[4])!);
    return { value: format(shift(now, n, unit), kind) };
  }
  return null;
}

function normalizeUnit(raw: string): string {
  const u = raw.toLowerCase();
  if (u.startsWith("mo")) return "mo";
  if (u.startsWith("y")) return "y";
  if (u.startsWith("w")) return "w";
  if (u.startsWith("d")) return "d";
  if (u.startsWith("h")) return "h";
  if (u === "m" || u.startsWith("mi")) return "m";
  if (u.startsWith("s")) return "s";
  return u;
}

/** The date kind a JSON Schema `format` names, or null. */
export function dateKindOf(format: unknown): DateKind | null {
  return format === "date" ? "date" : format === "date-time" ? "date-time" : null;
}
